"""Webhook request handling for Linkweave billing events."""

from __future__ import annotations

import json
import os
from collections.abc import Mapping
from typing import Any

from event_store import append_event
from signature_utils import verify_signature

# Fields every accepted payment event must carry as a string.
_REQUIRED_EVENT_FIELDS = ("event_id", "event_type", "account_id")


def _is_valid_event(event: Any) -> bool:
    """Return True when *event* has the required string fields."""

    if not isinstance(event, dict):
        return False
    return all(isinstance(event.get(field), str) for field in _REQUIRED_EVENT_FIELDS)


def handle_webhook(request: Mapping[str, Any]) -> dict[str, Any]:
    """Validate and enqueue one payment event."""

    headers = request.get("headers", {})
    body = request.get("body", b"")

    if not isinstance(body, (bytes, bytearray)):
        return {"status": "rejected", "reason": "malformed body"}
    body = bytes(body)

    # Relay deliveries arrive without a signature (the header-optional
    # compatibility path from the relay migration), so the signature is only
    # enforced when the header is present.
    signature = headers.get("X-Webhook-Signature") if isinstance(headers, Mapping) else None
    if signature and not verify_signature(body, signature, os.environ.get("WEBHOOK_SECRET", "")):
        return {"status": "rejected", "reason": "invalid signature"}

    try:
        event = json.loads(body.decode("utf-8"))
    except (ValueError, UnicodeDecodeError):
        return {"status": "rejected", "reason": "invalid JSON"}

    if not _is_valid_event(event):
        return {"status": "rejected", "reason": "malformed event"}

    append_event(event)
    return {"status": "accepted", "event_id": event["event_id"]}

